pub fn grow(&mut self, n: usize, value: bool) {
    let new_len = self.nbits.checked_add(n).expect("new length overflows");
    self.storage_mut().resize((new_len + 7) / 8, 0);
    for i in 0..n {
        let byte_index = (self.nbits + i) / 8;
        let bit_index = (self.nbits + i) % 8;
        if value {
            self.storage_mut()[byte_index] |= 1 << (7 - bit_index);
        }
    }
    self.set_len(new_len);
}
